/**
 * Supported currencies.
 *
 * @trace DSN-012 REQ-001 REQ-005
 */
export enum Currency { CHF = 'CHF', EUR = 'EUR', USD = 'USD' }

/**
 * Lifecycle state of an item auction.
 *
 * @trace DSN-013 REQ-001 REQ-004
 */
export enum AuctionStatus {
  open = 'open',
  closed = 'closed',
  unsold = 'unsold',
}

/**
 * User identified by unique display name.
 *
 * @trace DSN-014 REQ-008
 */
export class User {
  private static readonly MIN_LENGTH = 2;
  private static readonly MAX_LENGTH = 20;

  constructor(public id: string, public displayName: string) {
    if (!id || id.trim().length === 0) {
      throw new Error('User id must not be empty');
    }
    User.validateDisplayName(displayName);
  }

  private static validateDisplayName(name: string): void {
    const length = name.trim().length;
    if (length < User.MIN_LENGTH || length > User.MAX_LENGTH) {
      throw new Error(
        `Display name must be between ${User.MIN_LENGTH} and ${User.MAX_LENGTH} characters`,
      );
    }
  }
}

import { User } from './User.js';
import { UserService } from './UserService.js';

/**
 * HTTP routes for users: POST /users.
 *
 * @trace DSN-018 REQ-008
 */
export class UserController {
  constructor(private readonly userService: UserService) {}

  /**
   * Registers a user by display name and returns the issued user.
   */
  async register(displayName: string): Promise<User> {
    return this.userService.register(displayName);
  }
}

import { Item } from './Item.js';
import { Currency } from './Currency.js';

/**
 * Item as shown to a client, with optional converted prices.
 *
 * @trace DSN-017 REQ-005 REQ-010
 */
export interface ItemView {
  item: Item;
  displayCurrency: Currency | null;
  convertedStartingPrice: number | null;
  convertedHighestBid: number | null;
}

import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

const EXTENSION_WINDOW_MS = 2 * 60 * 1000;
const EXTENSION_MS = 2 * 60 * 1000;
const MIN_INCREMENT = 1;

/**
 * Auction item, prices in item currency.
 *
 * @trace DSN-015 REQ-001 REQ-002 REQ-004 REQ-009
 */
export class Item {
  constructor(
    public id: string,
    public sellerId: string,
    public title: string,
    public startingPrice: number,
    public currency: Currency,
    public endTime: Date,
    public status: AuctionStatus,
    public highestBidAmount: number | null,
    public highestBidderId: string | null,
    public winnerId: string | null,
  ) {
    if (!Object.values(Currency).includes(currency)) {
      throw new Error(`Currency ${String(currency)} is not supported`);
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('End time is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('Starting price must be a non-negative number');
    }
  }

  isOpen(now: Date): boolean {
    return this.status === AuctionStatus.open && now.getTime() < this.endTime.getTime();
  }

  minimumBid(): number {
    if (this.highestBidAmount === null) {
      return this.startingPrice;
    }
    return this.highestBidAmount + MIN_INCREMENT;
  }

  extendIfLate(now: Date): boolean {
    if (!this.isOpen(now)) {
      return false;
    }
    const remaining = this.endTime.getTime() - now.getTime();
    if (remaining <= EXTENSION_WINDOW_MS) {
      this.endTime = new Date(this.endTime.getTime() + EXTENSION_MS);
      return true;
    }
    return false;
  }
}

