import { ItemService } from './ItemService.js';
import { Item } from './Item.js';
import { ItemView } from './ItemView.js';

const SUPPORTED_CURRENCIES: readonly string[] = ['CHF', 'EUR', 'USD'];

/**
 * HTTP routes for items: POST /items, GET /items, GET /items/:id.
 *
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService) {}

  /**
   * Lists a new item for auction after validating its fields.
   */
  async listItem(
    userId: string,
    title: string,
    startingPrice: number,
    endTime: string,
    currency: string,
  ): Promise<Item> {
    if (!userId || userId.trim() === '') {
      throw new Error('Seller id is required');
    }
    if (!title || title.trim() === '') {
      throw new Error('Title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice)) {
      throw new Error('Starting price is required');
    }
    if (startingPrice < 0) {
      throw new Error('Starting price must not be negative');
    }
    if (!endTime) {
      throw new Error('End time is required');
    }
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) {
      throw new Error(`Invalid end time: ${endTime}`);
    }
    if (!currency) {
      throw new Error('Currency is required');
    }
    if (!SUPPORTED_CURRENCIES.includes(currency)) {
      throw new Error(`Unsupported currency: ${currency}`);
    }
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /**
   * Returns one item, with its display currency when a supported one is requested.
   */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (displayCurrency !== undefined && !SUPPORTED_CURRENCIES.includes(displayCurrency)) {
      throw new Error(`Unsupported display currency: ${displayCurrency}`);
    }
    const item = await this.itemService.getItem(id);
    const view: ItemView = {
      item,
      displayCurrency: displayCurrency === undefined
        ? null
        : (displayCurrency as ItemView['displayCurrency']),
      convertedStartingPrice: null,
      convertedHighestBid: null,
    };
    return view;
  }

  /**
   * Lists all auctions that are currently open.
   */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }
}

import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  private timer: ReturnType<typeof setInterval> | null = null;

  constructor(private readonly itemService: ItemService, public intervalMs: number) {
    if (!Number.isFinite(intervalMs) || intervalMs <= 0) {
      throw new Error('intervalMs must be a positive number');
    }
  }

  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }

  private start(): void {
    if (this.timer !== null) {
      return;
    }
    this.timer = setInterval(() => {
      void this.tick();
    }, this.intervalMs);
  }

  private stop(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  private timer: ReturnType<typeof setInterval> | null = null;

  constructor(private readonly itemService: ItemService, public intervalMs: number) {
    if (!Number.isFinite(intervalMs) || intervalMs <= 0) {
      throw new Error('intervalMs must be a positive number');
    }
  }

  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }

  private start(): void {
    if (this.timer !== null) {
      return;
    }
    this.timer = setInterval(() => {
      void this.tick();
    }, this.intervalMs);
  }

  private stop(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';

/**
 * Validates and stores bids, extends end time, publishes events to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  private nextBidNumber = 1;

  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new Error('Bid amount must be a positive number');
    }
    if (!bidderId || bidderId.trim() === '') {
      throw new Error('Bidder id is required');
    }
    const item = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const now = new Date();
    if (!item.isOpen(now)) {
      throw new Error(`Item ${itemId} is not open for bids`);
    }
    if (item.sellerId === bidderId) {
      throw new Error('Sellers cannot bid on their own item');
    }
    const minimum = item.minimumBid();
    if (amount < minimum) {
      throw new Error(`Bid ${amount} is below the minimum bid ${minimum}`);
    }

    const bid = new Bid(
      `bid-${this.nextBidNumber++}`,
      item.id,
      bidderId,
      amount,
      now,
    );

    item.highestBidAmount = amount;
    item.highestBidderId = bidderId;
    item.extendIfLate(now);

    await this.itemStore.saveBid(bid);
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(bid, item);
    return bid;
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using rates cached 1 hour; returns null when unavailable.
 *
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache: Map<Currency, CachedRates> = new Map();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error('Amount must be a non-negative number');
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.getRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number' || !Number.isFinite(rate)) {
      return null;
    }
    return amount * rate;
  }

  private async getRates(base: Currency): Promise<Record<string, number> | null> {
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: now });
      return rates;
    } catch {
      return null;
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { UserStore } from './UserStore.js';
import { ItemStore } from './ItemStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';

type ItemCurrency = Item['currency'];
type ItemStatus = Item['status'];

const ALLOWED_CURRENCIES: readonly string[] = ['CHF', 'EUR', 'USD'];

/**
 * Creates and reads items, closes due auctions.
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (!sellerId || sellerId.trim() === '') {
      throw new Error('Seller id is required');
    }
    if (!title || title.trim() === '') {
      throw new Error('Title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('Starting price is required and must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('End time is required');
    }
    if (endTime.getTime() <= Date.now()) {
      throw new Error('End time must be in the future');
    }
    if (!currency || !ALLOWED_CURRENCIES.includes(currency)) {
      throw new Error('Currency must be one of CHF, EUR or USD');
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as ItemCurrency,
      endTime,
      'Open' as unknown as ItemStatus,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  async getItem(id: string): Promise<Item> {
    const item = await this.itemStore.findItem(id);
    if (!item) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  async closeDueAuctions(now: Date): Promise<void> {
    const dueItems = await this.itemStore.findDueItems(now);
    for (const item of dueItems) {
      if (item.extendIfLate(now)) {
        await this.itemStore.saveItem(item);
        continue;
      }
      if (item.highestBidderId !== null) {
        item.winnerId = item.highestBidderId;
        item.status = 'Closed' as unknown as ItemStatus;
      } else {
        item.winnerId = null;
        item.status = 'Unsold' as unknown as ItemStatus;
      }
      await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(item);
    }
  }
}

