   * Lists a new item for auction after validating its fields.
   */
  async listItem(
    userId: string,
    title: string,
    startingPrice: number,
    endTime: string,
    currency: string,
  ): Promise<Item> {
    if (!userId || userId.trim() === '') {
      throw new Error('Seller id is required');
    }
    if (!title || title.trim() === '') {
      throw new Error('Title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice)) {
      throw new Error('Starting price is required');
    }
    if (startingPrice < 0) {
      throw new Error('Starting price must not be negative');
    }
    if (!endTime) {
      throw new Error('End time is required');
    }
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) {
      throw new Error(`Invalid end time: ${endTime}`);
    }
    if (!currency) {
      throw new Error('Currency is required');
    }
    if (!SUPPORTED_CURRENCIES.includes(currency)) {
      throw new Error(`Unsupported currency: ${currency}`);
    }
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /**
   * Returns one item, with its display currency when a supported one is requested.
   */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (displayCurrency !== undefined && !SUPPORTED_CURRENCIES.includes(displayCurrency)) {
      throw new Error(`Unsupported display currency: ${displayCurrency}`);
    }
    const item = await this.itemService.getItem(id);
    const view: ItemView = {
      item,
      displayCurrency: displayCurrency === undefined
        ? null
        : (displayCurrency as ItemView['displayCurrency']),
      convertedStartingPrice: null,
      convertedHighestBid: null,
    };
    return view;
  }

  /**
   * Lists all auctions that are currently open.
   */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }
}
