  constructor(private readonly eventFeed: EventFeed) {}

  /**
   * Publishes an accepted bid to the watchers of its item.
   */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (!bid || !item) {
      throw new Error('Bid and item are required');
