    const topic = `item:${item.id}`;
    const payload = JSON.stringify({
      type: 'bid.accepted',
      bidId: bid.id,
      itemId: item.id,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
    });
    this.eventFeed.publish(topic, payload);
  }
}
